// Un ítem por noticia. Les sumamos qué palabras clave aparecen y si son recientes.
const config = $('Fuente y palabras').first().json;

// Minúsculas y sin tildes, para comparar «Educación» con «educacion».
const normalizar = (t) => String(t ?? '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase();
// Para usar una palabra dentro de una expresión regular sin que sus signos cambien el significado.
const escapar = (t) => t.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');

// Cada palabra como la escribiste y en su versión para comparar.
const palabras = (config.palabras ?? []).map((p) => String(p).trim()).filter(Boolean).map((p) => ({ original: p, buscar: normalizar(p) }));
const desde = $now.minus({ days: config.dias ?? 7 });

return $input.all().map((item) => {
  const n = item.json;
  const texto = normalizar(`${n.title ?? ''} ${n.contentSnippet ?? ''}`);
  // \b = borde de palabra: busca la palabra entera.
  const coincidencias = palabras.filter((p) => new RegExp(`\\b${escapar(p.buscar)}\\b`).test(texto)).map((p) => p.original);
  const fecha = n.isoDate ? DateTime.fromISO(n.isoDate) : null;
  return {
    json: {
      titulo: n.title,
      enlace: n.link,
      fecha_iso: n.isoDate ?? '',
      fecha: fecha ? fecha.setZone('America/La_Paz').setLocale('es').toFormat("d 'de' LLLL") : '',
      resumen: String(n.contentSnippet ?? '').slice(0, 300),
      coincidencias,
      reciente: fecha ? fecha >= desde : true,
    },
  };
});

// Juntamos todas las noticias en un ítem, con un texto listo para mandar.
const noticias = $input.all().map((i) => i.json).filter((n) => n.titulo);
const config = $('Fuente y palabras').first().json;
const hoy = $now.setZone('America/La_Paz').setLocale('es').toFormat("cccc d 'de' LLLL");

if (!noticias.length) {
  return [{ json: { cantidad: 0, texto: `Resumen del ${hoy}: hoy no hubo noticias recientes con tus palabras (${config.palabras.join(', ')}).` } }];
}

const lineas = noticias.map((n) => `- ${n.titulo} (${n.fecha}). Habla de: ${n.coincidencias.join(', ')}.\n  ${n.enlace}`);
return [{
  json: {
    cantidad: noticias.length,
    texto: `Resumen del ${hoy}: ${noticias.length} noticias que te pueden interesar.\n\n${lineas.join('\n')}\n\nFuente: Noticias ONU.`,
    noticias,
  },
}];

